"use client";

import { Envelope as EnvelopePrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const envelopeVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "h-48",
      lg: "h-64",
      sm: "h-32",
    },
  },
});

interface EnvelopeProps
  extends EnvelopePrimitive.RootProps,
    VariantProps<typeof envelopeVariants> {}

export function Envelope({ className, size, ...props }: EnvelopeProps) {
  return (
    <EnvelopePrimitive.Root
      className="w-full data-[disabled=true]:cursor-not-allowed"
      {...props}
    >
      <EnvelopePrimitive.Svg
        className={cn(
          "rounded-none border border-transparent bg-card ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-1 hover:ring-ring/50 has-[:focus-visible]:ring-1 has-[:focus-visible]:ring-ring/50 active:ring-1 active:ring-ring/50 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none w-full touch-none select-none overflow-hidden",
          "focus-visible:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          envelopeVariants({ size }),
          className
        )}
        data-slot="envelope"
      >
        <EnvelopePrimitive.Fill className="fill-primary/15 stroke-none" />
        <EnvelopePrimitive.Path className="stroke-primary stroke-2" />
      </EnvelopePrimitive.Svg>
      <EnvelopePrimitive.Points>
        {(_point, index) => (
          <EnvelopePrimitive.Point
            className="border-ring border bg-card size-3.5 transition-[color,box-shadow] hover:ring-1 hover:ring-ring/50 focus-visible:ring-1 focus-visible:ring-ring/50 active:ring-1 active:ring-ring/50 data-[disabled=true]:pointer-events-none motion-reduce:transition-none cursor-grab touch-none select-none outline-none active:cursor-grabbing"
            index={index}
            key={index}
          />
        )}
      </EnvelopePrimitive.Points>
    </EnvelopePrimitive.Root>
  );
}
